import fs from "node:fs";
import path from "node:path";

const permissionDirectory = path.join(
  "apps",
  "desktop",
  "src-tauri",
  "permissions",
  "autogenerated",
);
const capabilityPath = path.join(
  "apps",
  "desktop",
  "src-tauri",
  "capabilities",
  "default.json",
);
const errors = [];

function readMatches(source, expression) {
  return [...source.matchAll(expression)].map((match) => match[1]);
}

if (!fs.existsSync(permissionDirectory)) {
  console.error(`Tauri permission directory not found: ${permissionDirectory}`);
  process.exit(1);
}
if (!fs.existsSync(capabilityPath)) {
  console.error(`Tauri capability file not found: ${capabilityPath}`);
  process.exit(1);
}

let capability;
try {
  capability = JSON.parse(fs.readFileSync(capabilityPath, "utf8"));
} catch (error) {
  console.error(`Could not parse Tauri capability JSON: ${error.message}`);
  process.exit(1);
}

if (!Array.isArray(capability.permissions)) {
  console.error("Tauri capability must contain a permissions array.");
  process.exit(1);
}

const files = fs
  .readdirSync(permissionDirectory)
  .filter((file) => file.endsWith(".toml"))
  .sort();
const identifiers = new Map();
const allowIdentifiers = new Set();

if (files.length === 0) errors.push("No autogenerated command permission files were found.");

for (const file of files) {
  const filePath = path.join(permissionDirectory, file);
  const source = fs.readFileSync(filePath, "utf8");
  const permissionIds = readMatches(
    source,
    /^identifier\s*=\s*"([^"]+)"\s*$/gm,
  );
  const allowCommands = readMatches(
    source,
    /^commands\.allow\s*=\s*\["([^"]+)"\]\s*$/gm,
  );
  const denyCommands = readMatches(
    source,
    /^commands\.deny\s*=\s*\["([^"]+)"\]\s*$/gm,
  );

  if (allowCommands.length !== 1 || denyCommands.length !== 1) {
    errors.push(`${file}: expected exactly one commands.allow and one commands.deny entry`);
    continue;
  }

  const command = allowCommands[0];
  if (denyCommands[0] !== command) {
    errors.push(`${file}: allow and deny entries must target the same command`);
  }
  if (file !== `${command}.toml`) {
    errors.push(`${file}: filename must match command "${command}"`);
  }

  const expected = [
    `allow-${command.replaceAll("_", "-")}`,
    `deny-${command.replaceAll("_", "-")}`,
  ];
  if (permissionIds.length !== 2) {
    errors.push(`${file}: expected exactly two permission identifiers`);
  }
  for (const id of expected) {
    if (!permissionIds.includes(id)) {
      errors.push(`${file}: missing expected identifier "${id}"`);
    }
  }

  for (const id of permissionIds) {
    if (identifiers.has(id)) {
      errors.push(`${file}: duplicate permission identifier "${id}" also found in ${identifiers.get(id)}`);
    } else {
      identifiers.set(id, file);
    }
  }
  if (expected[0]) allowIdentifiers.add(expected[0]);
}

const capabilityPermissions = new Set(capability.permissions);
if (capabilityPermissions.size !== capability.permissions.length) {
  errors.push("default capability contains duplicate permission entries");
}

for (const permission of capabilityPermissions) {
  if (permission.startsWith("core:") || permission.startsWith("opener:")) continue;
  if (!identifiers.has(permission)) {
    errors.push(`default capability references missing permission "${permission}"`);
  }
}

for (const permission of allowIdentifiers) {
  if (!capabilityPermissions.has(permission)) {
    errors.push(`default capability does not grant registered command permission "${permission}"`);
  }
}

if (errors.length > 0) {
  console.error("Tauri ACL validation failed:");
  for (const error of errors) console.error(` - ${error}`);
  process.exit(1);
}

console.log(
  `Tauri ACL validation passed: ${files.length} command files, ${identifiers.size} permission IDs, ${capability.permissions.length} capability entries.`,
);
